def solve_sequence_A(N):
    if N == 0:
        return {}

    a = {1: 0}

    for n in range(2, N + 1):
        if n % 2 == 0:
            # n = 2k => k = n/2
            k = n // 2
            if k not in a:
                # Should not happen if calculating sequentially
                print(f"Error: a_{k} not found when calculating a_{n}")
                return None
            a[n] = 2 * a[k] + k
        else:
            # n = 2k + 1 => 2k = n - 1 => k = (n - 1) / 2
            k = (n - 1) // 2
            kp1 = k + 1
            if k not in a or kp1 not in a:
                print(f"Error: a_{k} or a_{kp1} not found when calculating a_{n}")
                return None
            a[n] = a[k] + a[kp1] + k

    return a

